const $=id=>document.getElementById(id), video=$('video');
const client=crypto.randomUUID();
let code=sessionStorage.getItem('cowatch-room')||'', state=null, connected=false;
let operation=0;
let generation=0, busy=false, sending=false, pending=null, dragging=false, entering=false, mediaError=false;
const format=n=>`${Math.floor(n/60).toString().padStart(2,'0')}:${Math.floor(n%60).toString().padStart(2,'0')}`;
async function api(action,data={},room=code){
  const controller=new AbortController(), timer=setTimeout(()=>controller.abort(),3000);
  try {
    const r=await fetch('/api/'+action,{method:'POST',signal:controller.signal,headers:{'Content-Type':'application/json'},body:JSON.stringify({client,code:room,...data})});
    const d=await r.json();if(!r.ok){const e=Error(d.error);e.status=r.status;throw e;}return d;
  } finally {clearTimeout(timer);}
}
function showRoom(){
  $('entry').hidden=!!code;$('room').hidden=!code;$('roomCode').textContent=code;
  $('toggle').disabled=$('seek').disabled=!code||!connected||mediaError||video.readyState<1;
  $('create').disabled=entering;$('join').querySelector('button').disabled=entering;
}
function status(){
  if(!code)return;
  if(!connected){$('members').textContent='在线窗口数未知 · 连接未确认';return;}
  $('members').textContent=`${state.members} 个窗口近期有响应（含本窗口） · 不代表均已播放`;
  $('toggle').textContent=state.playing?'暂停':'播放';
  $('status').textContent=mediaError?'本窗口视频加载失败，尚未同步播放。':video.readyState<1?'房间已连接，正在加载本窗口视频…':state.playing?(video.paused?'房间正在播放，本窗口尚未播放。':video.readyState<3?'房间正在播放，本窗口缓冲中…':'本窗口正在跟随房间播放 · 双方均可操作'):'房间已暂停 · 双方均可操作';
}
function failed(e){
  connected=false;pending=null;dragging=false;video.pause();$('unlock').hidden=true;showRoom();status();
  $('status').textContent=e.status===404?'房间已失效，请离开后重新创建或加入。':'连接中断或请求超时，已暂停本窗口，正在重试…';
  $('error').textContent=e.status===404?e.message:'操作结果可能未确认；恢复后以房间状态为准，不重发断线操作。';
}
async function apply(s,g=generation){
  if(g!==generation||s.code!==code||(state&&s.revision<state.revision))return;
  state=s;connected=true;showRoom();status();
  if(video.readyState<1||dragging||sending||mediaError)return;
  if(Math.abs(video.currentTime-s.position)>.65)video.currentTime=s.position;
  if(s.playing){
    video.play().then(()=>{
      if(g!==generation||!connected||!state?.playing){video.pause();return;}
      $('unlock').hidden=true;status();
    }).catch(()=>{if(g===generation&&connected&&state?.playing){$('unlock').hidden=false;status();}});
  }else{video.pause();$('unlock').hidden=true;}
  if(g===generation)status();
}
async function enter(action,data={}){
  if(entering)return;entering=true;showRoom();const g=++generation;
  try{const s=await api(action,data);if(g!==generation)return;code=s.code;state=null;sessionStorage.setItem('cowatch-room',code);$('error').textContent='';await apply(s,g);}
  catch(e){if(g===generation)$('error').textContent=e.name==='AbortError'?'连接超时，请重试。':e.message;}
  finally{entering=false;showRoom();}
}
$('create').onclick=()=>enter('create');
$('join').onsubmit=e=>{e.preventDefault();enter('state',{code:$('code').value.trim().toUpperCase()});};
async function control(position,playing){
  if(!connected||!code)return;
  ++operation;
  pending={position,playing};if(sending)return; sending=true;const g=generation;
  try{while(pending&&g===generation){const next=pending;pending=null;const s=await api('control',next);if(g!==generation)return;state=s;}}
  catch(e){if(g===generation)failed(e);}
  finally{sending=false;if(g===generation&&connected)poll();}
}
$('toggle').onclick=()=>control(video.currentTime,!(pending?.playing??state?.playing));
$('seek').oninput=()=>{dragging=true;$('time').textContent=format(Number($('seek').value))+' / 01:30';};
$('seek').onchange=()=>{dragging=false;if(connected)control(Number($('seek').value),!!state?.playing);};
$('seek').onblur=()=>{dragging=false;};
$('unlock').onclick=async()=>{if(!connected||!state?.playing)return;const g=generation;try{await video.play();if(g!==generation||!connected||!state?.playing)video.pause();else{$('unlock').hidden=true;status();poll();}}catch{$('error').textContent='浏览器仍未允许播放，请检查媒体设置。';}};
$('fullscreen').onclick=()=>{if(video.requestFullscreen)video.requestFullscreen().catch(()=>{$('error').textContent='此浏览器暂不支持全屏。';});else $('error').textContent='此浏览器暂不支持全屏。';};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(code);$('copy').textContent='已复制房间码';setTimeout(()=>$('copy').textContent='复制房间码',1800);}catch{$('error').textContent='复制不可用，请选中上方房间码手动复制。';}};
$('second').onclick=()=>window.open(location.origin+'/?room='+code,'_blank','width=1100,height=850');
$('leave').onclick=()=>{
  const old=code;++generation;code='';state=null;pending=null;dragging=false;connected=false;
  sessionStorage.removeItem('cowatch-room');video.pause();$('unlock').hidden=true;$('error').textContent='';showRoom();$('status').textContent='已离开，可创建或加入其他房间。';
  api('leave',{},old).catch(()=>{});
};
async function poll(){
  if(!code||busy||sending)return;busy=true;const g=generation,op=operation;
  try{const s=await api('state');if(g!==generation||op!==operation)return;await apply(s,g);if(g===generation)$('error').textContent=mediaError?'视频无法加载。请检查本机服务后刷新页面重试。':'';}
  catch(e){if(g===generation&&op===operation)failed(e);}
  finally{busy=false;}
}
video.onloadedmetadata=()=>{mediaError=false;showRoom();if(state)apply(state);};
video.ontimeupdate=()=>{if(!dragging){$('seek').value=video.currentTime;$('time').textContent=format(video.currentTime)+' / '+format(video.duration||90);}};
video.onerror=()=>{mediaError=true;showRoom();status();$('error').textContent='视频无法加载或格式不受支持。请检查本机服务后刷新页面重试。';};
for(const event of ['waiting','playing','pause','canplay','ended'])video.addEventListener(event,status);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});
const initial=new URLSearchParams(location.search).get('room');if(initial){code='';$('code').value=initial;}
if(code)$('status').textContent='正在重新连接上次房间…';
showRoom();status();poll();setInterval(poll,400);

