import json, mimetypes, secrets, threading, time, webbrowser
from pathlib import Path
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler

ROOT = Path(__file__).resolve().parent
rooms = {}
lock = threading.Lock()

def snapshot(room):
    now = time.monotonic()
    room['members'] = {k: v for k, v in room['members'].items() if now-v < 8}
    pos = min(90, room['position'] + (now-room['at'] if room['playing'] else 0))
    return dict(position=pos, playing=room['playing'] and pos < 90,
                revision=room['revision'], members=len(room['members']))

class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args): pass
    def reply(self, status, value):
        data = json.dumps(value).encode()
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Content-Length', str(len(data)))
        self.end_headers(); self.wfile.write(data)
    def do_POST(self):
        if self.headers.get('Origin') not in (None, 'http://127.0.0.1:8765', 'http://localhost:8765'):
            return self.reply(403, {'error':'鏉ユ簮涓嶅厑璁?})
        try:
            length = int(self.headers.get('Content-Length', 0))
            if not 0 < length < 4096: raise ValueError()
            body = json.loads(self.rfile.read(length))
            client = body['client']
            if not isinstance(client, str) or not 1 <= len(client) <= 100: raise ValueError()
            with lock:
                if self.path == '/api/create':
                    code = ''.join(secrets.choice('ABCDEFGHJKLMNPQRSTUVWXYZ23456789') for _ in range(6))
                    while code in rooms: code = secrets.token_hex(3).upper()
                    rooms[code] = dict(position=0, playing=False, at=time.monotonic(), revision=0, members={})
                else: code = str(body.get('code', '')).upper()
                if code not in rooms: return self.reply(404, {'error':'鎴块棿涓嶅瓨鍦紝璇锋鏌ユ埧闂寸爜鎴栭噸鏂板垱寤恒€?})
                room = rooms[code]
                if self.path == '/api/leave': room['members'].pop(client, None)
                else: room['members'][client] = time.monotonic()
                if self.path == '/api/control':
                    position = float(body['position'])
                    if not 0 <= position <= 90 or type(body['playing']) is not bool: raise ValueError()
                    room.update(position=position, playing=body['playing'], at=time.monotonic(), revision=room['revision']+1)
                elif self.path not in ('/api/create','/api/state','/api/leave'): return self.reply(404, {'error':'鏃犳鎿嶄綔'})
                self.reply(200, dict(code=code, **snapshot(room)))
        except (ValueError, KeyError, TypeError): self.reply(400, {'error':'璇锋眰鏍煎紡涓嶆纭?})
    def do_GET(self):
        path = self.path.split('?')[0]
        file = {'/': ROOT/'app/index.html', '/app.js': ROOT/'app/app.js', '/style.css': ROOT/'app/style.css', '/video.mp4': ROOT/'inputs/婕旂ず.mp4'}.get(path)
        if file is None: self.send_error(404); return
        size = file.stat().st_size
        start, end, status = 0, size-1, 200
        value = self.headers.get('Range')
        if value:
            try:
                unit, span = value.split('='); a,b = span.split('-')
                if unit != 'bytes': raise ValueError()
                start = int(a) if a else max(0,size-int(b))
                end = min(int(b), size-1) if b and a else size-1
                if start < 0 or start > end: raise ValueError()
                status = 206
            except ValueError:
                self.send_response(416); self.send_header('Content-Range', f'bytes */{size}'); self.end_headers(); return
        self.send_response(status)
        self.send_header('Content-Type', mimetypes.guess_type(str(file))[0] or 'application/octet-stream')
        self.send_header('Accept-Ranges', 'bytes')
        self.send_header('Content-Length', str(end-start+1))
        if status == 206: self.send_header('Content-Range', f'bytes {start}-{end}/{size}')
        self.end_headers()
        try:
            with file.open('rb') as f:
                f.seek(start); remaining=end-start+1
                while remaining:
                    chunk=f.read(min(65536,remaining))
                    if not chunk: break
                    self.wfile.write(chunk); remaining-=len(chunk)
        except (ConnectionAbortedError, ConnectionResetError, BrokenPipeError): pass

if __name__ == '__main__':
    server = ThreadingHTTPServer(('127.0.0.1', 8765), Handler)
    print('涓€璧风湅宸插惎鍔細http://127.0.0.1:8765  鍏抽棴姝ょ獥鍙ｅ嵆鍙仠姝€?, flush=True)
