const $=id=>document.getElementById(id), video=$('video');
const client=crypto.randomUUID();
let code=localStorage.getItem('cowatch-room')||'', state=null, busy=false, sending=false, pending=null, dragging=false, connected=false;
const format=n=>`${Math.floor(n/60).toString().padStart(2,'0')}:${Math.floor(n%60).toString().padStart(2,'0')}`;
async function api(action,data={}){const r=await fetch('/api/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({client,code,...data})});const d=await r.json();if(!r.ok)throw Error(d.error);return d;}
function showRoom(){ $('entry').hidden=!!code;$('room').hidden=!code;$('roomCode').textContent=code; $('toggle').disabled=$('seek').disabled=!code||!connected; }
async function apply(s){if(s.code!==code||(state?.code===s.code&&s.revision<state.revision))return;state=s;connected=true;showRoom();$('members').textContent=`${s.members} 个窗口在线 · 自动同步`;if(video.readyState<1||dragging||sending)return; if(Math.abs(video.currentTime-s.position)>.65)video.currentTime=s.position; if(s.playing){try{await video.play();$('unlock').hidden=true;}catch{$('unlock').hidden=false;}}else{video.pause();$('unlock').hidden=true;}$('toggle').textContent=s.playing?'暂停':'播放';$('status').textContent=s.playing?'正在同步播放 · 双方均可操作':'已同步暂停 · 双方均可操作';}
async function enter(action,data){try{const s=await api(action,data);code=s.code;state=null;localStorage.setItem('cowatch-room',code);$('error').textContent='';await apply(s);}catch(e){$('error').textContent=e.message;}}
$('create').onclick=()=>enter('create');
$('join').onsubmit=e=>{e.preventDefault();enter('state',{code:$('code').value.trim().toUpperCase()});};
async function control(position,playing){pending={position,playing};if(sending)return;sending=true;try{while(pending){const next=pending;pending=null;const s=await api('control',next);state=s;}sending=false;await poll();}catch(e){sending=false;connected=false;showRoom();$('error').textContent='连接中断，操作未确认。恢复后将重新跟随房间。';}}
$('toggle').onclick=()=>control(video.currentTime,!state?.playing);
$('seek').oninput=()=>{dragging=true;$('time').textContent=format(Number($('seek').value))+' / 01:30';};
$('seek').onchange=()=>{dragging=false;video.currentTime=Number($('seek').value);control(video.currentTime,!!state?.playing);};
$('unlock').onclick=async()=>{try{await video.play();$('unlock').hidden=true;await poll();}catch{$('error').textContent='浏览器仍未允许播放，请检查媒体设置。';}};
$('fullscreen').onclick=()=>video.requestFullscreen?.().catch(()=>{$('error').textContent='此浏览器暂不支持全屏。';});
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(code);$('copy').textContent='已复制房间码';setTimeout(()=>$('copy').textContent='复制房间码',1800);}catch{$('error').textContent='复制不可用，请选中上方房间码手动复制。';}};
$('second').onclick=()=>window.open(location.origin+'/?room='+code,'_blank','width=1100,height=850');
$('leave').onclick=async()=>{try{await api('leave');}catch{}code='';state=null;localStorage.removeItem('cowatch-room');video.pause();connected=false;showRoom();$('status').textContent='已离开，可创建或加入其他房间。';};
async function poll(){if(!code||busy||sending)return;busy=true;try{await apply(await api('state'));$('error').textContent='';}catch(e){connected=false;showRoom();video.pause();$('status').textContent='连接中断，正在重试…';$('error').textContent=e.message;}finally{busy=false;}}
video.onloadedmetadata=()=>{if(state)apply(state);};
video.ontimeupdate=()=>{if(!dragging){$('seek').value=video.currentTime;$('time').textContent=format(video.currentTime)+' / '+format(video.duration||90);}};
video.onerror=()=>{$('error').textContent='视频无法加载或格式不受支持，请用本机 Chrome 或 Edge 重试。';};
document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});
const initial=new URLSearchParams(location.search).get('room');if(initial){code='';$('code').value=initial;}
showRoom();poll();setInterval(poll,400);
