const $=id=>document.getElementById(id), video=$('video');
const client=crypto.randomUUID();
let code=localStorage.getItem('cowatch-room')||'', state=null, busy=false, sending=false, dragging=false, connected=false;
let epoch=0, entering=false, lastConfirmed=0, blocked=false, mediaFailed=false, applying=0;
const format=n=>`${Math.floor(n/60).toString().padStart(2,'0')}:${Math.floor(n%60).toString().padStart(2,'0')}`;
async function api(action,data={}){
  const abort=new AbortController(), timer=setTimeout(()=>abort.abort(),3000);
  try{
    const r=await fetch('/api/'+action,{method:'POST',signal:abort.signal,headers:{'Content-Type':'application/json'},body:JSON.stringify({client,code,...data})});
    const d=await r.json();if(!r.ok){const e=Error(d.error);e.status=r.status;throw e;}return d;
  }finally{clearTimeout(timer);}
}
function showRoom(){
  $('entry').hidden=!!code;$('room').hidden=!code;$('roomCode').textContent=code;
  $('create').disabled=entering;$('code').disabled=entering;
  $('toggle').disabled=$('seek').disabled=!code||!connected||sending||video.readyState<1||mediaFailed;
  $('unlock').hidden=!code||!connected||!blocked||!state?.playing||mediaFailed;
  if(!code)return;
  const stamp=lastConfirmed?new Date(lastConfirmed).toLocaleTimeString():'';
  $('members').textContent=connected?`${state.members} 个窗口近期有响应（8 秒内） · 不代表均已播放`:
    state?`连接未确认 · 上次 ${stamp} 确认 ${state.members} 个窗口；当前人数未知`:'连接未确认 · 当前人数未知';
  $('toggle').textContent=state?.playing?'暂停':'播放';
  let text;
  if(!connected)text='连接中断或尚未确认，已暂停本窗口；正在重试…';
  else if(sending)text='正在提交操作，尚未确认…';
  else if(mediaFailed)text='房间已连接，但本窗口视频加载失败。请点击重试视频。';
  else if(video.readyState<1)text='房间已连接，正在加载本窗口视频；若长时间等待可重试视频。';
  else if(dragging)text='正在选择进度，松开后提交到房间。';
  else if(state.playing){
    text=blocked?'房间正在播放，本窗口被浏览器阻止；请点击启用播放。':
      video.paused||video.readyState<3?'房间正在播放，本窗口等待播放或缓冲…':'房间正在播放 · 本窗口正在播放（不代表其他窗口已播放）';
  }else text='房间已暂停 · 本窗口已暂停';
  $('status').textContent=text;
}
function lost(e,operation=false){
  connected=false;blocked=false;dragging=false;applying++;video.pause();
  $('error').textContent=e.status===404?'房间已不存在（服务重启会清空房间）。请离开后新建或加入其他房间。':
    operation?'操作未确认，可能已被服务接收；恢复后以房间状态为准，不自动重发。':'暂时无法确认房间状态，将自动重试。';
  showRoom();
}
async function apply(s,confirm=true){
  if(s.code!==code||(state?.code===s.code&&s.revision<state.revision))return;
  state=s;if(confirm){connected=true;lastConfirmed=Date.now();}
  const token=++applying, session=epoch;
  if(video.readyState>=1&&!mediaFailed&&!dragging&&!sending){
    if(Math.abs(video.currentTime-s.position)>.65)video.currentTime=s.position;
    if(s.playing){try{await video.play();if(token===applying)blocked=false;}catch{if(token===applying)blocked=true;}}
    else{video.pause();blocked=false;}
  }
  if(session!==epoch||token!==applying){if(!connected||!code)video.pause();return;}
  showRoom();
}
async function enter(action,data){
  if(entering)return;entering=true;const session=++epoch;showRoom();
  try{const s=await api(action,data);if(session!==epoch)return;code=s.code;state=null;localStorage.setItem('cowatch-room',code);$('error').textContent='';await apply(s);}
  catch(e){if(session===epoch)$('error').textContent=e.message||'连接失败，请重试。';}
  finally{if(session===epoch){entering=false;showRoom();}}
}
$('create').onclick=()=>enter('create');
$('join').onsubmit=e=>{e.preventDefault();enter('state',{code:$('code').value.trim().toUpperCase()});};
async function control(position,playing){
  if(!connected||sending||!code)return;
  sending=true;const session=epoch;showRoom();
  try{const s=await api('control',{position,playing});if(session!==epoch)return;sending=false;$('error').textContent='';await apply(s);}
  catch(e){if(session===epoch){sending=false;lost(e,true);}}
  finally{if(session===epoch){sending=false;showRoom();}}
}
$('toggle').onclick=()=>control(video.currentTime,!state?.playing);
$('seek').oninput=()=>{dragging=true;$('time').textContent=format(Number($('seek').value))+' / '+format(video.duration||90);showRoom();};
$('seek').onchange=()=>{dragging=false;if(connected)control(Number($('seek').value),!!state?.playing);};
$('seek').onpointercancel=()=>{dragging=false;poll();};
$('seek').onblur=()=>{if(dragging){dragging=false;poll();}};
$('unlock').onclick=async()=>{if(connected&&state?.playing)await apply(state,false);};
$('retryVideo').hidden=false;
$('retryVideo').onclick=()=>{mediaFailed=false;blocked=false;video.src='/video.mp4?retry='+Date.now();video.load();showRoom();poll();};
$('fullscreen').onclick=()=>{if(!video.requestFullscreen){$('error').textContent='此浏览器暂不支持全屏。';return;}video.requestFullscreen().catch(()=>{$('error').textContent='此浏览器暂不支持全屏。';});};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(code);$('copy').textContent='已复制房间码';setTimeout(()=>$('copy').textContent='复制房间码',1800);}catch{$('error').textContent='复制不可用，请选中上方房间码手动复制。';}};
$('second').onclick=()=>window.open(location.origin+'/?room='+code,'_blank','width=1100,height=850');
$('leave').onclick=()=>{
  const old=code;epoch++;applying++;code='';state=null;connected=false;sending=false;busy=false;dragging=false;blocked=false;entering=false;
  localStorage.removeItem('cowatch-room');video.pause();showRoom();$('error').textContent='';$('status').textContent='已离开，可创建或加入其他房间。';
  history.replaceState(null,'',location.pathname);api('leave',{code:old}).catch(()=>{});
};
async function poll(){
  if(!code||busy||sending)return;busy=true;const session=epoch;
  try{const s=await api('state');if(session!==epoch||sending)return;await apply(s);if(session===epoch&&connected)$('error').textContent='';}
  catch(e){if(session===epoch&&!sending)lost(e);}
  finally{if(session===epoch)busy=false;}
}
video.onloadedmetadata=()=>{mediaFailed=false;if(state&&connected)apply(state,false);else showRoom();};
video.ontimeupdate=()=>{if(!dragging){$('seek').value=video.currentTime;$('time').textContent=format(video.currentTime)+' / '+format(video.duration||90);}};
video.onerror=()=>{mediaFailed=true;video.pause();$('retryVideo').hidden=false;showRoom();};
video.onloadeddata=()=>{showRoom();};
for(const event of ['playing','waiting','pause','ended','stalled'])video.addEventListener(event,showRoom);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});
window.addEventListener('offline',()=>{if(code)lost(Error('offline'));});
window.addEventListener('online',poll);
const initial=new URLSearchParams(location.search).get('room');if(initial){code='';$('code').value=initial;}
showRoom();poll();setInterval(poll,400);
